insert into public.skill_definitions
  (id, name, description, kind, hidden, conditions, effect, locks, owner_limit, evolves_from, excludes, uses_per_battle, rumor, enabled)
values
  ('blade_read', 'Blade Read', 'After a parry, your next slash can''t miss and always crits. 3 parries in a row: that slash ignores defense. 20 parries in a row: your next slash one-shots any monster that isn''t a boss. Needs a sword in hand.', 'passive', true, '{"counter":"parries","op":">=","value":1000}'::jsonb, '{"weapons":["sword"],"passive":{"blade_read":{"pierce_at":3,"execute_at":20}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('hundred_cuts', 'Hundred Cuts', 'Each hit in a row adds 2% damage. 50 in a row: slashes also hit enemies next to your target. 100 in a row: a slash hits every enemy on screen. Getting hit resets the count to 0. Needs a sword in hand.', 'passive', true, '{"counter":"hit_streak_best","op":">=","value":100}'::jsonb, '{"weapons":["sword"],"passive":{"hundred_cuts":{"per_hit":0.02,"adjacent_at":50,"screen_at":100}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('duelists_oath', 'Duelist''s Oath', '+30% STR while fighting a single enemy. Turns off when more enemies join.', 'passive', true, '{"counter":"boss_duels_won","op":">=","value":50}'::jsonb, '{"passive":{"duelist":{"stat":"STR","mult":1.3}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('broken_blade', 'Broken Blade', 'Broken swords deal double damage, and a sword breaking mid-fight makes its shards explode.', 'passive', true, '{"counter":"broken_blade_kills","op":">=","value":300}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('parry_emperor', 'Parry Emperor', 'Ultimate, bosses only. Each successful parry against a boss charges the gauge (a missed parry doesn''t drain it). 25: counter for 50% of the boss''s HP (once per fight, resets the gauge). 50: a full kill. 100: a full kill + 20% EXP. Fire or keep charging at each tier.', 'active', true, '{"counter":"boss_fight_parry_dmg_best","op":">=","value":100000}'::jsonb, '{"active":{"ultimate":{"gauge":"boss_parries","tiers":[25,50,100]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('retribution', 'Retribution', 'Ultimate, bosses only. Each boss attack you survive charges the gauge (a multi-strike swing counts once). 50: counter for 50% of the boss''s HP (once per fight, resets the gauge). 100: a full kill. 200: a full kill + 20% EXP. Fire or keep charging at each tier.', 'active', true, '{"counter":"boss_fight_hits_best","op":">=","value":50}'::jsonb, '{"active":{"ultimate":{"gauge":"boss_hits","tiers":[50,100,200]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('titans_defiance', 'Titan''s Defiance', 'Against a higher-level monster, after 5 defends (20 against a boss) you become immune to damage for 10 seconds. 15 minute cooldown. Hits taken while immune still count toward Retribution.', 'passive', true, '{"counter":"titan_kills","op":">=","value":1}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('iron_riposte', 'Iron Riposte', 'Every perfect block (a parry with your shield) automatically strikes back with VIT-based damage.', 'passive', true, '{"counter":"perfect_blocks","op":">=","value":1000}'::jsonb, '{"weapons":["large_shield"],"passive":{"riposte":{"multiplier":1,"scale_stat":"VIT","element":"physical"}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('vengeance_vault', 'Vengeance Vault', 'Damage you block while guarding is stored. Let go of block to release it as one piercing shockwave.', 'passive', true, '{"counter":"damage_taken","op":">=","value":1000000}'::jsonb, '{"passive":{"vault":true}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('eye_of_the_storm', 'Eye of the Storm', 'Every enemy hit you take strikes back at all the enemies around you at once, with VIT-based damage.', 'passive', true, '{"counter":"storm_fights_survived","op":">=","value":100}'::jsonb, '{"passive":{"storm":{"multiplier":1,"scale_stat":"VIT","element":"physical","area":true}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('wanderers_path', 'Wanderer''s Path', 'All your masteries grow 10% faster.', 'passive', true, '{"counter":"masteries_lv20","op":">=","value":5}'::jsonb, '{"passive":{"mastery_growth":1.1}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('adaptive_body', 'Adaptive Body', '+10% to all stats.', 'passive', true, '{"all":[{"player":"level","op":">=","value":30},{"stat_spread":true,"op":"<=","value":5}]}'::jsonb, '{"stat_multiplier":{"HP":1.1,"MP":1.1,"STR":1.1,"VIT":1.1,"AGI":1.1,"DEX":1.1,"INT":1.1}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true)
